import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Overall Architecture and Data Flow","description":"Hearth's North Star architecture, seven planes, task data flow, deployment topologies, and architectural evolution.","frontmatter":{"title":"Overall Architecture and Data Flow","description":"Hearth's North Star architecture, seven planes, task data flow, deployment topologies, and architectural evolution.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/overview.md","filePath":"en/architecture/overview.md","lastUpdated":1793706118000}`),o={name:"en/architecture/overview.md"};function r(i,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<p class="eyebrow">SYSTEM DESIGN</p><h1 id="overall-architecture-and-data-flow" tabindex="-1">Overall Architecture and Data Flow <a class="header-anchor" href="#overall-architecture-and-data-flow" aria-label="Permalink to &quot;Overall Architecture and Data Flow&quot;">​</a></h1><p class="lead">How the seven planes work together, how state flows, and how the system grows from a minimal product into a complete Agent OS.</p><h2 id="north-star-architecture" tabindex="-1">North Star Architecture <a class="header-anchor" href="#north-star-architecture" aria-label="Permalink to &quot;North Star Architecture&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User / CLI / Web / Mobile / IM</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Experience Plane</span></span>
<span class="line"><span>     Task Card · Approval · Artifact · Takeover</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Personal Gateway</span></span>
<span class="line"><span>   Identity · Channel · Device · Attention Entry</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>       Control Plane</span></span>
<span class="line"><span>  Trigger · Policy · Mandate · Scheduling · Watchdog</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Durable Harness</span></span>
<span class="line"><span>  Task Graph · Budget · lease · Retry · Recovery</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>       Executor Layer</span></span>
<span class="line"><span> Native · Codex · Connector · Browser</span></span>
<span class="line"><span> GUI · Document/Data · Human</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Execution Gateway</span></span>
<span class="line"><span> Workspace · Sandbox · Network · Credential Broker</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>  Event Log / Artifacts / Receipts</span></span>
<span class="line"><span>       ↓              ↓</span></span>
<span class="line"><span>   Memory OS      Evolution OS</span></span></code></pre></div><p>All facts enter the Event Log; all external side effects go through the outbox, idempotency keys, and Receipts; all UI state is a projection, not a source of truth.</p><h2 id="the-seven-planes" tabindex="-1">The Seven Planes <a class="header-anchor" href="#the-seven-planes" aria-label="Permalink to &quot;The Seven Planes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plane</th><th>Responsibility</th><th>Not responsible for</th></tr></thead><tbody><tr><td>Experience Plane</td><td>Task cards, approvals, artifacts, takeover, notifications</td><td>Directly executing business logic or writing to the database</td></tr><tr><td>Personal Gateway</td><td>Identity, channel normalization, device registration, attention entry point</td><td>Long-running task reasoning</td></tr><tr><td>Control Plane</td><td>Intent, triggers, Policy, Mandate, scheduling, Watchdog</td><td>Holding long-term credentials</td></tr><tr><td>Durable Harness</td><td>Task graph, routing, budget, retries, lease, recovery</td><td>Bypassing Policy to execute external actions</td></tr><tr><td>Executor Layer</td><td>Unified protocol for Native, Codex, Connector, Browser, GUI, Document/Data, Human</td><td>Expanding its own permissions or modifying Policy</td></tr><tr><td>Execution Gateway</td><td>Workspace, Sandbox, browser, GUI, network, Credential Broker</td><td>Deciding &quot;whether it should be done&quot;</td></tr><tr><td>Memory / Evolution</td><td>Personal context, memory, skills, evaluation, promotion and rollback</td><td>Becoming a source of truth</td></tr></tbody></table><p>The Event Log runs through all planes and is the source for state, auditing, recovery, and UI.</p><h2 id="complete-data-flow-of-a-task" tabindex="-1">Complete Data Flow of a Task <a class="header-anchor" href="#complete-data-flow-of-a-task" aria-label="Permalink to &quot;Complete Data Flow of a Task&quot;">​</a></h2><ol><li>A user or Source produces an event.</li><li>The Gateway normalizes the Event, deduplicates it, and records its source.</li><li>The Control Plane decides: ignore / observe / suggest / create Task.</li><li>Policy and Mandate check scope, risk, budget, and approval requirements.</li><li>The Token Router selects the minimum viable model and execution tier.</li><li>The Context Compiler builds the Task Pack.</li><li>The Harness creates the Ticket, Assignment, and outbox record.</li><li>The Executor executes in a restricted environment, continuously producing WorkerEvents.</li><li>The Execution Gateway completes approved side effects through the Broker.</li><li>Artifacts, Receipts, failures, and human actions are written to the Event Log.</li><li>The validator decides to complete, retry, switch executors, or hand off to a human.</li><li>Memory writes candidate memories; Evolution collects trajectories.</li><li>The UI generates task cards, notifications, and artifact views from projections.</li></ol><h2 id="deployment-forms" tabindex="-1">Deployment Forms <a class="header-anchor" href="#deployment-forms" aria-label="Permalink to &quot;Deployment Forms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Composition</th><th>Goal</th></tr></thead><tbody><tr><td>Local</td><td><code>hearth</code> CLI + <code>hearthd</code> + SQLite + Docker</td><td>Phase one and dogfood</td></tr><tr><td>Hybrid</td><td>Local state and device capabilities + cloud models/sandboxes</td><td>Insufficient resources or remote execution</td></tr><tr><td>Self-hosted Server</td><td>Always-on Gateway + multi-device agentd + optional remote Sandbox</td><td>Long-term online presence and multiple devices</td></tr></tbody></table><p>Phase one does not introduce microservices. A single process, single writer, and SQLite are sufficient to support the early stage. Module boundaries are guaranteed by interfaces, schemas, and tests, rather than by splitting into network services first.</p><h2 id="startup-forms" tabindex="-1">Startup Forms <a class="header-anchor" href="#startup-forms" aria-label="Permalink to &quot;Startup Forms&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearthd</span></span>
<span class="line"><span>  ├─ local gateway / IPC / web API</span></span>
<span class="line"><span>  ├─ scheduler / watcher / trigger</span></span>
<span class="line"><span>  ├─ task queue / event log / outbox</span></span>
<span class="line"><span>  ├─ token router / context compiler / budget governor</span></span>
<span class="line"><span>  ├─ executor supervisor</span></span>
<span class="line"><span>  ├─ device registry / capability catalog / lease manager</span></span>
<span class="line"><span>  ├─ execution gateway / sandbox manager</span></span>
<span class="line"><span>  ├─ watchdog / health / backup</span></span>
<span class="line"><span>  └─ pairing / event sync / device revocation</span></span></code></pre></div><p>Must account for auto-start on boot, continued operation after the terminal closes, sleep/wake, network interruptions, authentication expiry, Executor crashes, version upgrades, resource reclamation, phone disconnection, and re-pairing.</p><h2 id="architecture-evolution" tabindex="-1">Architecture Evolution <a class="header-anchor" href="#architecture-evolution" aria-label="Permalink to &quot;Architecture Evolution&quot;">​</a></h2><p>Hearth does not implement all modules in the final architecture diagram on day one. The architecture grows incrementally with the product, but the core invariants remain:</p><table tabindex="0"><thead><tr><th>Product Form</th><th>Architectural Increment</th><th>Remains Unchanged</th></tr></thead><tbody><tr><td>Stage 0 clickable prototype</td><td>Web prototype, UI data contract, simulated projection</td><td>Task-card-first, honest state, one primary action</td></tr><tr><td>Stage 1 local MVP</td><td>single-process <code>hearthd</code>, SQLite WAL, Event Log, Codex, basic approvals and Artifacts</td><td>source of truth, recovery, verification, side-effect Receipt</td></tr><tr><td>Stage 2 daily operator</td><td>Connector, Browser, Document/Data, Context Compiler, Memory v0</td><td>least privilege, provenance, idempotency, Token budget</td></tr><tr><td>Stage 3 desktop operator</td><td>device agentd, GUI Executor, takeover and desktop isolation</td><td>single-writer, audit, approvals, failure recovery</td></tr><tr><td>Stage 4 proactive personal Agent</td><td>Trigger, attention budget, mobile PWA, push and pairing</td><td>low-interruption, revocable, proactive mode can be paused</td></tr><tr><td>Stage 5 Memory and Evolution OS</td><td>Memory OS, Evolution OS, skill evaluation and rollback</td><td>provenance, forgetting, permission intersection, rollback-capable</td></tr><tr><td>Stage 6 Personal Agent OS v1.0</td><td>multi-device sync, offline queue, migration, long-running operation and quotas</td><td>one logical Agent, event consistency, revocable devices</td></tr></tbody></table><p><strong>Architecture can expand in stages, but the product form cannot be retrofitted in stages.</strong> Every stage must have a complete user path matching its architectural complexity.</p><h2 id="chapter-conclusion" tabindex="-1">Chapter Conclusion <a class="header-anchor" href="#chapter-conclusion" aria-label="Permalink to &quot;Chapter Conclusion&quot;">​</a></h2><p>The value of architecture is not the number of modules, but letting “Task, Mandate, execution, evidence, and recovery” flow along the same auditable chain. Stage 0 defines the contract first, Stage 1 implements it with the smallest real chain, and afterward the planes expand gradually without changing the source of truth and permission boundaries.</p>`,23)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
